// Render a context window of `radius` bytes around `offset` as escaped text,
// with a caret marking the exact offset. The window edges are nudged to UTF-8
// character boundaries so no replacement chars (U+FFFD) appear in the output.
function byteContext(buf, offset, radius) {
  let start = Math.max(0, offset - radius);
  let end = Math.min(buf.length, offset + radius);
