// argparse.mjs
// Replicates the Python argparse CLI of test14.py:
//   parser = argparse.ArgumentParser(description="Complex markdown processing chain")
//   parser.add_argument('--a', type=str, required=True)
//   parser.add_argument('--b', type=str, required=True)
// Behavior was verified byte-for-byte against the reference executable
// (usage/error text, exit codes, abbreviations, `--` handling, negative numbers).
// The prog name is `test14.mjs` (the basename a Python script of that name would show).

const PROG = 'test14.mjs';

const USAGE = `usage: ${PROG} [-h] --a A --b B`;

const HELP = `${USAGE}

Complex markdown processing chain

options:
  -h, --help  show this help message and exit
  --a A
  --b B
`;

const LONG_OPTIONS = ['--a', '--b', '--help'];

function fail(message) {
  process.stderr.write(USAGE + '\n');
  process.stderr.write(`${PROG}: error: ${message}\n`);
  process.exit(2);
}

function showHelp() {
  process.stdout.write(HELP);
  process.exit(0);
}

function isAllDigits(s) {
  if (s.length === 0) return false;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c < 48 || c > 57) return false;
  }
  return true;
}

// Matches argparse's _negative_number_matcher: ^-\d+$ or ^-\d*\.\d+$
// (relevant because no defined option string looks like a negative number).
function isNegativeNumber(s) {
  if (s.length < 2 || s[0] !== '-') return false;
  const rest = s.slice(1);
  if (isAllDigits(rest)) return true;
  const dot = rest.indexOf('.');
  if (dot === -1) return false;
  const intPart = rest.slice(0, dot);
  const fracPart = rest.slice(dot + 1);
  if (intPart.length > 0 && !isAllDigits(intPart)) return false;
  return isAllDigits(fracPart);
}

// Mirrors argparse._parse_optional: decides whether a token looks like an
// option string (vs. a positional/value).
function isOptionLike(token) {
  if (token.length === 0 || token[0] !== '-') return false;
  if (token === '-') return false; // a single dash is a value
  if (isNegativeNumber(token)) return false;
  if (token.indexOf(' ') !== -1) return false; // tokens with spaces are values
  return true;
}

// Exact match, then unambiguous abbreviation (argparse allow_abbrev=True).
function matchLongOption(name) {
  for (const opt of LONG_OPTIONS) {
    if (opt === name) return opt;
  }
  let found = null;
  for (const opt of LONG_OPTIONS) {
    if (opt.startsWith(name)) {
      if (found !== null) {
        fail(`ambiguous option: ${name} could match ${found}, ${opt}`);
      }
      found = opt;
    }
  }
  return found;
}

export function parseArgs(argv) {
  const result = { a: undefined, b: undefined };
  const extras = [];
  let optionsEnabled = true;
  let i = 0;

  while (i < argv.length) {
    const token = argv[i];

    // First `--` disables option parsing; with no positionals defined, the
    // `--` itself and everything after it land in the unrecognized extras.
    if (optionsEnabled && token === '--') {
      optionsEnabled = false;
      extras.push(token);
      i++;
      continue;
    }

    if (optionsEnabled && isOptionLike(token)) {
      if (token.startsWith('--')) {
        // Long option, possibly in --name=value form.
        let name = token;
        let explicit;
        const eq = token.indexOf('=');
        if (eq !== -1) {
          name = token.slice(0, eq);
          explicit = token.slice(eq + 1);
        }
        const match = matchLongOption(name);
        if (match === null) {
          // Unrecognized long option: the whole token becomes an extra.
          extras.push(token);
          i++;
          continue;
        }
        if (match === '--help') {
          if (explicit !== undefined) {
            fail(`argument -h/--help: ignored explicit argument '${explicit}'`);
          }
          showHelp();
        }
        // --a or --b: each requires exactly one value.
        let value;
        if (explicit !== undefined) {
          value = explicit;
        } else {
          const next = argv[i + 1];
          if (next === undefined || next === '--' || isOptionLike(next)) {
            fail(`argument ${match}: expected one argument`);
          }
          value = next;
          i++;
        }
        result[match === '--a' ? 'a' : 'b'] = value;
        i++;
        continue;
      }
      // Single-dash token: -h (with anything appended) fires help;
      // anything else is an unrecognized extra.
      if (token[1] === 'h') {
        showHelp();
      }
      extras.push(token);
      i++;
      continue;
    }

    // Positional token (none are defined) -> unrecognized extra.
    extras.push(token);
    i++;
  }

  // Missing-required check fires before the unrecognized-extras check.
  const missing = [];
  if (result.a === undefined) missing.push('--a');
  if (result.b === undefined) missing.push('--b');
  if (missing.length > 0) {
    fail(`the following arguments are required: ${missing.join(', ')}`);
  }
  if (extras.length > 0) {
    fail(`unrecognized arguments: ${extras.join(' ')}`);
  }

  return result;
}

