// Extract zlib-inflated module payloads from a PyInstaller PYZ archive.
import { readFileSync, writeFileSync } from 'node:fs';
import { inflateSync } from 'node:zlib';

const buf = readFileSync('/workspace/dataset/test14_executable');
// PyInstaller cookie: magic 'MEI\x0c\x0b\x0a\x0b\x0e' at end (88 bytes for v2.1+)
const MAGIC = Buffer.from([0x4d, 0x45, 0x49, 0x0c, 0x0b, 0x0a, 0x0b, 0x0e]);
let cookiePos = -1;
for (let i = buf.length - 88; i >= 0; i--) {
  if (buf[i] === 0x4d && buf.compare(MAGIC, 0, 8, i, i + 8) === 0) { cookiePos = i; break; }
}
if (cookiePos < 0) { console.error('no cookie'); process.exit(1); }
const pkgLen = buf.readUInt32BE(cookiePos + 8);
const tocPos = buf.readUInt32BE(cookiePos + 12);
const tocLen = buf.readUInt32BE(cookiePos + 16);
const base = cookiePos + 88 - pkgLen; // start of the CArchive
let p = base + tocPos;
const tocEnd = p + tocLen;
let pyzEntry = null;
while (p < tocEnd) {
  const entryLen = buf.readUInt32BE(p);
  const entryPos = buf.readUInt32BE(p + 4);
  const entrySize = buf.readUInt32BE(p + 8);
  const csize = buf.readUInt32BE(p + 12);
  const typ = String.fromCharCode(buf[p + 16]);
  // name: null-terminated string starting at p+18 (pyi v2.1: entry = 4*4+1+1+name)
  let nameEnd = p + 18;
  while (buf[nameEnd] !== 0) nameEnd++;
  const name = buf.toString('latin1', p + 18, nameEnd);
  if (name === 'PYZ.pyz' || typ === 'z' || typ === 'Z') pyzEntry = { pos: base + entryPos, size: entrySize, csize };
  p += entryLen;
}
if (!pyzEntry) { console.error('no PYZ'); process.exit(1); }
// Parse PYZ: magic 'PYZ\0', pyc magic(4), toc offset(4)
const pyz = buf.subarray(pyzEntry.pos, pyzEntry.pos + pyzEntry.size);
const pyzTocPos = pyz.readUInt32BE(8);
// PYZ toc is a marshaled list of tuples (name, (typ, offset, length)). Parse marshal manually.
let q = pyzTocPos;
function readByte() { return pyz[q++]; }
function readLong() { const v = pyz.readInt32LE(q); q += 4; return v; }
function readString(n) { const s = pyz.toString('latin1', q, q + n); q += n; return s; }
function parseObj() {
  let t = readByte();
  // const flag = t & 0x80; t &= 0x7f; // refs only for interned strings; we ignore ref table
  t &= 0x7f;
  switch (String.fromCharCode(t)) {
    case '(': { const n = readLong(); const a = []; for (let i = 0; i < n; i++) a.push(parseObj()); return a; }
    case '[': { const n = readLong(); const a = []; for (let i = 0; i < n; i++) a.push(parseObj()); return a; }
    case 's': { const n = readLong(); return readString(n); }
    case 'a': case 'A': case 'z': case 'Z': { const n = readByte(); return readString(n); }
    case 'u': { const n = readLong(); return readString(n); }
    case 'i': return readLong();
    case 'I': { const v = Number(pyz.readBigInt64LE(q)); q += 8; return v; }
    case '0': case 'N': case 'T': case 'F': case '.': return null;
    case '<': case '>': case '{': case '}': throw new Error('set/dict not supported');
    default: throw new Error('unknown marshal type ' + String.fromCharCode(t) + ' (' + t + ') at ' + q);
  }
}
const toc = parseObj();
let count = 0;
for (const [name, meta] of toc) {
  if (!name.startsWith('markdown')) continue;
  const [typ, off, len] = meta;
  const blob = pyz.subarray(off, off + len);
  const data = inflateSync(blob);
  writeFileSync('/tmp/pyx/' + name.replace(/\./g, '_') + '.bin', data);
  count++;
}
console.log('extracted', count, 'modules');

